-- =============================================================================
-- MM YoteShin — initial schema
-- =============================================================================
-- This migration is the source of truth for the database structure.
-- `src/db/schema.ts` mirrors it for type-safe queries; the two must be kept in
-- step. See docs/deployment.md for how migrations are applied.
--
-- Conventions:
--   * UUID primary keys generated by the database.
--   * `timestamptz` everywhere, always stored in UTC.
--   * Explicit foreign keys with deliberate ON DELETE behaviour.
--   * CHECK constraints for invariants that must hold regardless of code path.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------

CREATE TYPE movie_status AS ENUM ('draft', 'published', 'archived');
CREATE TYPE review_status AS ENUM ('draft', 'published', 'archived');

-- Distinguishes an editorial score from a community score or a third-party
-- aggregate, so a number is never displayed without its provenance.
CREATE TYPE rating_source AS ENUM ('editorial', 'community', 'external_aggregate');

CREATE TYPE link_status AS ENUM ('pending_review', 'active', 'disabled', 'reported');

-- The recorded legal basis for distributing or linking to a file.
CREATE TYPE authorization_basis AS ENUM (
  'public_domain',
  'open_license',
  'distribution_agreement',
  'written_permission',
  'publisher_authorized_page',
  'other_documented'
);

CREATE TYPE report_status AS ENUM ('new', 'under_review', 'resolved', 'rejected');

CREATE TYPE report_reason AS ENUM (
  'broken_link',
  'copyright',
  'unauthorized_distribution',
  'malware_or_unsafe',
  'misleading_listing',
  'metadata_error',
  'other'
);

CREATE TYPE admin_role AS ENUM ('owner', 'admin', 'editor');

-- -----------------------------------------------------------------------------
-- Shared trigger: keep updated_at honest
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

-- -----------------------------------------------------------------------------
-- Identity
-- -----------------------------------------------------------------------------

-- Credentials. Authorisation lives in admin_profiles so a role can be changed
-- without touching secrets.
CREATE TABLE admin_users (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email              varchar(320) NOT NULL,
  password_hash      text         NOT NULL,
  display_name       varchar(120) NOT NULL,
  is_active          boolean      NOT NULL DEFAULT true,
  last_login_at      timestamptz,
  failed_login_count integer      NOT NULL DEFAULT 0,
  locked_until       timestamptz,
  created_at         timestamptz  NOT NULL DEFAULT now(),
  updated_at         timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT admin_users_email_lowercase CHECK (email = lower(email))
);

-- Emails are stored lower-cased, so a plain unique index is sufficient
-- (avoids depending on the citext extension).
CREATE UNIQUE INDEX admin_users_email_key ON admin_users (email);

CREATE TRIGGER admin_users_set_updated_at
  BEFORE UPDATE ON admin_users
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE admin_profiles (
  user_id    uuid PRIMARY KEY REFERENCES admin_users (id) ON DELETE CASCADE,
  role       admin_role  NOT NULL DEFAULT 'editor',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX admin_profiles_role_idx ON admin_profiles (role);

CREATE TRIGGER admin_profiles_set_updated_at
  BEFORE UPDATE ON admin_profiles
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Catalogue
-- -----------------------------------------------------------------------------

CREATE TABLE movies (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title            varchar(300) NOT NULL,
  slug             varchar(320) NOT NULL,
  original_title   varchar(300),
  release_year     integer,
  release_date     date,
  runtime_minutes  integer,
  synopsis         text,
  -- Original editorial copy. Never copied from another site.
  editorial_note   text,
  poster_url       text,
  backdrop_url     text,
  -- Attribution for the poster/backdrop asset, surfaced in the admin UI.
  image_credit     varchar(300),
  language_code    varchar(12),
  country          varchar(80),
  content_rating   varchar(24),
  status           movie_status NOT NULL DEFAULT 'draft',
  featured         boolean      NOT NULL DEFAULT false,
  -- Manual ordering weight for curated rails; higher sorts first.
  curation_weight  integer      NOT NULL DEFAULT 0,
  meta_title       varchar(200),
  meta_description varchar(320),
  published_at     timestamptz,
  archived_at      timestamptz,
  created_by       uuid REFERENCES admin_users (id) ON DELETE SET NULL,
  updated_by       uuid REFERENCES admin_users (id) ON DELETE SET NULL,
  created_at       timestamptz  NOT NULL DEFAULT now(),
  updated_at       timestamptz  NOT NULL DEFAULT now(),

  CONSTRAINT movies_title_not_blank   CHECK (length(btrim(title)) > 0),
  CONSTRAINT movies_slug_not_blank    CHECK (length(btrim(slug)) > 0),
  CONSTRAINT movies_release_year_range
    CHECK (release_year IS NULL OR (release_year BETWEEN 1888 AND 2200)),
  CONSTRAINT movies_runtime_positive
    CHECK (runtime_minutes IS NULL OR runtime_minutes > 0),
  -- A published film must carry a publication timestamp; the public query
  -- layer depends on this pair.
  CONSTRAINT movies_published_requires_timestamp
    CHECK (status <> 'published' OR published_at IS NOT NULL)
);

CREATE UNIQUE INDEX movies_slug_key ON movies (slug);
CREATE INDEX movies_status_published_at_idx ON movies (status, published_at);
CREATE INDEX movies_release_year_idx ON movies (release_year);
CREATE INDEX movies_featured_idx ON movies (featured, curation_weight);

CREATE TRIGGER movies_set_updated_at
  BEFORE UPDATE ON movies
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE genres (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name          varchar(80) NOT NULL,
  slug          varchar(96) NOT NULL,
  description   text,
  display_order integer     NOT NULL DEFAULT 0,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX genres_slug_key ON genres (slug);
CREATE UNIQUE INDEX genres_name_key ON genres (name);
CREATE INDEX genres_display_order_idx ON genres (display_order);

CREATE TRIGGER genres_set_updated_at
  BEFORE UPDATE ON genres
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE movie_genres (
  movie_id uuid NOT NULL REFERENCES movies (id) ON DELETE CASCADE,
  genre_id uuid NOT NULL REFERENCES genres (id) ON DELETE CASCADE,
  PRIMARY KEY (movie_id, genre_id)
);

CREATE INDEX movie_genres_genre_idx ON movie_genres (genre_id);

-- -----------------------------------------------------------------------------
-- Editorial reviews
-- -----------------------------------------------------------------------------

CREATE TABLE reviews (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  movie_id      uuid NOT NULL REFERENCES movies (id) ON DELETE CASCADE,
  review_title  varchar(240),
  -- Plain text with paragraph breaks. Rendered as text nodes, never raw HTML.
  body          text         NOT NULL,
  rating        numeric(3,1),
  -- Documents what the number means, e.g. 10 = a 0–10 editorial scale.
  rating_scale  numeric(4,1) NOT NULL DEFAULT 10.0,
  rating_source rating_source NOT NULL DEFAULT 'editorial',
  reviewer_name varchar(120) NOT NULL,
  reviewer_id   uuid REFERENCES admin_users (id) ON DELETE SET NULL,
  status        review_status NOT NULL DEFAULT 'draft',
  published_at  timestamptz,
  created_at    timestamptz   NOT NULL DEFAULT now(),
  updated_at    timestamptz   NOT NULL DEFAULT now(),

  CONSTRAINT reviews_body_not_blank CHECK (length(btrim(body)) > 0),
  CONSTRAINT reviews_rating_range
    CHECK (rating IS NULL OR (rating >= 0 AND rating <= rating_scale)),
  CONSTRAINT reviews_published_requires_timestamp
    CHECK (status <> 'published' OR published_at IS NOT NULL)
);

CREATE INDEX reviews_status_idx ON reviews (status);
CREATE INDEX reviews_movie_idx ON reviews (movie_id);

-- At most one published review per film, so the detail page is unambiguous.
CREATE UNIQUE INDEX reviews_movie_published_key
  ON reviews (movie_id)
  WHERE status = 'published';

CREATE TRIGGER reviews_set_updated_at
  BEFORE UPDATE ON reviews
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Authorized external distribution links
-- -----------------------------------------------------------------------------

CREATE TABLE download_links (
  id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  movie_id                uuid NOT NULL REFERENCES movies (id) ON DELETE CASCADE,
  provider_name           varchar(160) NOT NULL,
  destination_url         text         NOT NULL,
  -- Normalised host, stored so reviews and audits can group by provider.
  destination_host        varchar(255) NOT NULL,
  label                   varchar(200) NOT NULL,
  quality                 varchar(40),
  file_size_bytes         numeric(20,0),
  language                varchar(60),
  authorization_basis     authorization_basis NOT NULL,
  -- Private evidence: contract reference, permission email ID, licence URL.
  -- NEVER returned to a public client — see src/db/queries/public.ts.
  authorization_reference text,
  authorization_notes     text,
  authorized_by           uuid REFERENCES admin_users (id) ON DELETE SET NULL,
  authorized_at           timestamptz,
  last_checked_at         timestamptz,
  last_checked_by         uuid REFERENCES admin_users (id) ON DELETE SET NULL,
  status                  link_status  NOT NULL DEFAULT 'pending_review',
  created_at              timestamptz  NOT NULL DEFAULT now(),
  updated_at              timestamptz  NOT NULL DEFAULT now(),

  CONSTRAINT download_links_destination_https
    CHECK (destination_url LIKE 'https://%'),
  CONSTRAINT download_links_file_size_non_negative
    CHECK (file_size_bytes IS NULL OR file_size_bytes >= 0),
  -- Defence in depth: the database refuses to hold an active link that has
  -- never been reviewed and authorised, no matter which code path wrote it.
  CONSTRAINT download_links_active_requires_authorization
    CHECK (
      status <> 'active'
      OR (authorization_basis IS NOT NULL AND authorized_at IS NOT NULL)
    )
);

CREATE INDEX download_links_movie_status_idx ON download_links (movie_id, status);
CREATE INDEX download_links_status_idx ON download_links (status);
CREATE INDEX download_links_host_idx ON download_links (destination_host);

CREATE TRIGGER download_links_set_updated_at
  BEFORE UPDATE ON download_links
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Content / link reports
-- -----------------------------------------------------------------------------

CREATE TABLE content_reports (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  movie_id         uuid REFERENCES movies (id) ON DELETE SET NULL,
  download_link_id uuid REFERENCES download_links (id) ON DELETE SET NULL,
  -- Optional — reports may be anonymous.
  reporter_contact varchar(320),
  reason           report_reason NOT NULL,
  details          text          NOT NULL,
  status           report_status NOT NULL DEFAULT 'new',
  -- Internal moderation notes. Never exposed publicly.
  resolution_notes text,
  resolved_by      uuid REFERENCES admin_users (id) ON DELETE SET NULL,
  resolved_at      timestamptz,
  -- Salted hash of the reporter IP — used only for abuse control.
  reporter_ip_hash varchar(128),
  created_at       timestamptz   NOT NULL DEFAULT now(),
  updated_at       timestamptz   NOT NULL DEFAULT now(),

  CONSTRAINT content_reports_details_not_blank CHECK (length(btrim(details)) > 0),
  CONSTRAINT content_reports_target_present
    CHECK (movie_id IS NOT NULL OR download_link_id IS NOT NULL)
);

CREATE INDEX content_reports_status_idx ON content_reports (status, created_at);
CREATE INDEX content_reports_movie_idx ON content_reports (movie_id);
CREATE INDEX content_reports_link_idx ON content_reports (download_link_id);

CREATE TRIGGER content_reports_set_updated_at
  BEFORE UPDATE ON content_reports
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Audit trail
-- -----------------------------------------------------------------------------

CREATE TABLE audit_logs (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_id    uuid REFERENCES admin_users (id) ON DELETE SET NULL,
  actor_email varchar(320),
  action      varchar(80) NOT NULL,
  entity_type varchar(40) NOT NULL,
  entity_id   uuid,
  summary     text        NOT NULL,
  -- Sanitised, non-sensitive context only. Never store secrets or evidence.
  metadata    jsonb,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX audit_logs_created_at_idx ON audit_logs (created_at);
CREATE INDEX audit_logs_entity_idx ON audit_logs (entity_type, entity_id);
CREATE INDEX audit_logs_actor_idx ON audit_logs (actor_id);

-- -----------------------------------------------------------------------------
-- Site settings (no secrets)
-- -----------------------------------------------------------------------------

CREATE TABLE site_settings (
  key        varchar(80) PRIMARY KEY,
  value      jsonb       NOT NULL,
  updated_by uuid REFERENCES admin_users (id) ON DELETE SET NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- -----------------------------------------------------------------------------
-- Durable rate limiting
-- -----------------------------------------------------------------------------

-- Backs the rate limiter so limits survive a cold start and hold across
-- serverless instances (an in-memory counter would not).
CREATE TABLE rate_limits (
  key               varchar(200) PRIMARY KEY,
  hit_count         integer     NOT NULL DEFAULT 0,
  window_started_at timestamptz NOT NULL DEFAULT now(),
  expires_at        timestamptz NOT NULL
);

CREATE INDEX rate_limits_expires_at_idx ON rate_limits (expires_at);
